        if payload.hire_date is not None:
            emp.hire_date = parse_date(payload.hire_date)
        if payload.active is not None:
            emp.active = payload.active

        emp.updated_at = datetime.now(timezone.utc)
        db.commit()
        db.refresh(emp)
        return emp

